document.addEventListener('change', ev => { if (['filter', 'formation', 'deckCount', 'handSort', 'handSortOrder'].includes(ev.target.dataset.act)) handleForm(ev.target) });
document.addEventListener('submit', ev => { if (ev.target.matches('#accountForm')) { ev.preventDefault(); accountSubmit(ev.target).catch(err => { accountNotice = 'エラー：' + err.message; render() }); return } if (!ev.target.matches('#cardManageForm')) return; ev.preventDefault(); try { let c = captureManageForm(); commitUserCards([c]); editingCard = null; managePanel = 'list'; render() } catch (e) { alert('登録できません：' + e.message) } });
document.addEventListener('change', async ev => { let a = ev.target.dataset.act; if (a === 'importTextFile') { let file = ev.target.files?.[0]; if (file) { pasteDraft = await file.text(); managePanel = 'import'; manageNotice = 'TXTファイルを読み込みました。内容を確認して「本文から取り込む」を押してください。'; render() } } else if (a === 'presetImportFile') { let file = ev.target.files?.[0]; if (file) try { let txt = await file.text(); if (txt.length > 750000) throw Error('JSONが大きすぎます'); let data = JSON.parse(txt); importNamedFormations(data); render() } catch (e) { presetNotice = '取り込み失敗：' + e.message; render() } } else if (a === 'deckImportFile') { let file = ev.target.files?.[0]; if (file) try { let parsed = JSON.parse(await file.text()); importDeckFile(parsed); render() } catch (e) { deckNotice = '取り込み失敗：' + e.message; render() } } else if (a === 'importJsonFile') { let file = ev.target.files?.[0]; if (file) try { let data = JSON.parse(await file.text()); let cards = Array.isArray(data) ? data : data.cards; if (!Array.isArray(cards)) throw Error('JSON配列または {cards: [...]} の形式で指定してください'); if (!confirm(cards.length + '枚のJSONカードを登録しますか？')) return; commitUserCards(cards); managePanel = 'list'; render() } catch (e) { alert('JSON取り込み失敗：' + e.message) } } });
document.addEventListener('dragstart', ev => { const slot = ev.target.closest('[data-field-slot]'); if (!slot || slot.getAttribute('draggable') !== 'true') return; fieldDragUid = slot.dataset.fieldSlot; fieldDragSide = slot.dataset.fieldSide; slot.classList.add('is-dragging'); if (ev.dataTransfer) { ev.dataTransfer.effectAllowed = 'move'; ev.dataTransfer.setData('text/plain', fieldDragUid) } });
document.addEventListener('dragover', ev => { const slot = ev.target.closest('[data-field-slot]'); if (!slot || !fieldDragUid || slot.dataset.fieldSide !== fieldDragSide) return; ev.preventDefault(); if (ev.dataTransfer) ev.dataTransfer.dropEffect = 'move'; document.querySelectorAll('.field-slot.drop-target').forEach(x => x.classList.remove('drop-target')); slot.classList.add('drop-target') });
document.addEventListener('drop', ev => { const slot = ev.target.closest('[data-field-slot]'); if (!slot || !fieldDragUid) return; ev.preventDefault(); const from = fieldDragUid, to = slot.dataset.fieldSlot, side = Number(slot.dataset.fieldSide); if (slot.dataset.fieldSide === fieldDragSide) reorderFieldUnits(side, from, to); fieldDragUid = null; fieldDragSide = null; render() });
document.addEventListener('dragend', () => { fieldDragUid = null; fieldDragSide = null; document.querySelectorAll('.field-slot.is-dragging,.field-slot.drop-target').forEach(x => x.classList.remove('is-dragging', 'drop-target')) });
initDeckBuilder(); initializeFormations(); restore(); render(); accountRestoreSession();
